<?php
session_start(); require_once __DIR__.'/_auth.php'; require_once __DIR__.'/../config/database.php';
function e($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function statusClass($s){return $s==='Selesai'?'done':($s==='Diproses'?'process':'wait');}
$stats=['total'=>0,'Menunggu'=>0,'Diproses'=>0,'Selesai'=>0];
$q=mysqli_query($conn,"SELECT status,COUNT(*) AS jumlah FROM laporan GROUP BY status");
if($q){while($r=mysqli_fetch_assoc($q)){if(isset($stats[$r['status']]))$stats[$r['status']]=(int)$r['jumlah'];$stats['total']+=(int)$r['jumlah'];}}
$sql="SELECT l.id,l.kategori,l.lokasi,l.status,l.tanggal,l.foto,u.nama AS nama_pelapor FROM laporan l LEFT JOIN users u ON l.user_id=u.id ORDER BY l.tanggal DESC,l.id DESC";
$result=mysqli_query($conn,$sql); if(!$result){http_response_code(500);exit('Gagal mengambil data laporan.');}
function fotoUrl($foto){$foto=trim((string)$foto);if($foto===''||preg_match('~^(https?:)?//~i',$foto)||strpos(str_replace('\\','/',$foto),'..')!==false)return '';return '../'.ltrim(str_replace('\\','/',$foto),'/');}
?>
