<?php if(mysqli_num_rows($result)===0):?><tr><td colspan="8" class="empty">Belum ada laporan.</td></tr><?php else:$no=1;while($r=mysqli_fetch_assoc($result)): $src=fotoUrl($r['foto']);?><tr><td><?=$no++?></td><td><?=e($r['nama_pelapor']??'Pengguna')?></td><td><?=e($r['kategori'])?></td><td><?=e($r['lokasi'])?></td><td><?php if($src):?><a href="<?=e($src)?>" target="_blank" rel="noopener"><img class="thumb" src="<?=e($src)?>" alt="Foto kerusakan"></a><?php else:?><span class="no-photo">Belum ada</span><?php endif;?></td><td><span class="status <?=statusClass($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['tanggal'])?></td><td class="no-print"><a class="btn light" href="detail.php?id=<?=(int)$r['id']?>">Detail / Kelola</a></td></tr><?php endwhile;endif;?>
